import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Список Самопроверки Противоречий Сеттинга","description":"","frontmatter":{},"headers":[],"relativePath":"ru/97-设定矛盾自查表.md","filePath":"ru/97-设定矛盾自查表.md","lastUpdated":1789183869000}'),h={name:"ru/97-设定矛盾自查表.md"};function i(l,t,o,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="список-самопроверки-противоречии-сеттинга" tabindex="-1">Список Самопроверки Противоречий Сеттинга <a class="header-anchor" href="#список-самопроверки-противоречии-сеттинга" aria-label="Permalink to &quot;Список Самопроверки Противоречий Сеттинга&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>97</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>самопроверка противоречий, согласованность сеттинга, логическая проверка, контроль качества, обслуживание сеттинга</td></tr></tbody></table><h2 id="i-пояснения" tabindex="-1">I. Пояснения <a class="header-anchor" href="#i-пояснения" aria-label="Permalink to &quot;I. Пояснения&quot;">​</a></h2><p>Список Самопроверки Противоречий Сеттинга — инструмент контроля качества системы сеттинга Симбиотической Цивилизации Якоря, используемый для систематического выявления возможных противоречий сеттинга и логических несоответствий при создании новых настроек, пересмотре старых настроек и обновлении документов. Настоящий список самопроверки составлен на основе 14 ключевых настроек и контрольного списка согласованности, установленных в SPEC.md, и охватывает все модули: мировоззрение, система культивации, общественный строй, правовая система, формы жизни, технологическая система, исторические эпохи, межплоскостное взаимодействие и др. Любая новая настройка или пересмотренное содержание должно пройти все пункты контроля настоящего списка до официального включения в систему сеттинга.</p><h2 id="ii-проверки-согласованности-ключевых-настроек" tabindex="-1">II. Проверки согласованности ключевых настроек <a class="header-anchor" href="#ii-проверки-согласованности-ключевых-настроек" aria-label="Permalink to &quot;II. Проверки согласованности ключевых настроек&quot;">​</a></h2><h3 id="_2-1-названия-вселеннои-и-основные-понятия" tabindex="-1">2.1 Названия вселенной и основные понятия <a class="header-anchor" href="#_2-1-названия-вселеннои-и-основные-понятия" aria-label="Permalink to &quot;2.1 Названия вселенной и основные понятия&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>C01</td><td>Единство названия вселенной</td><td>Во всём тексте единообразно используется «Изначальная Вселенная Ваньлин Хэнмао» или сокращение «Вселенная Хэнъюань»; другие названия не допускаются</td><td>Смешение нестандартных названий: «вселенная», «десять тысяч миров», «все небеса» и т. п.</td></tr><tr><td>C02</td><td>Согласованность определения Якоря</td><td>Якорь всегда определяется как «устойчивый узел в сети законов»; его сущностные свойства не могут быть изменены</td><td>Описание Якоря как предмета, существа или энергетического тела</td></tr><tr><td>C03</td><td>Единство концепции симбиоза</td><td>Симбиоз всегда означает «совместную эволюцию разных жизней через взаимовыгодное сотрудничество»; отклонение от анти-хищнической позиции не допускается</td><td>Описание симбиоза как ассимиляции, поглощения или контроля</td></tr><tr><td>C04</td><td>Согласованность ключевой позиции</td><td>Всегда придерживаться принципа «Реальность как основа»; вымышленные настройки не могут описываться как реальность</td><td>Смешение границы между вымыслом и реальностью</td></tr></tbody></table><h3 id="_2-2-согласованность-системы-культивации" tabindex="-1">2.2 Согласованность системы культивации <a class="header-anchor" href="#_2-2-согласованность-системы-культивации" aria-label="Permalink to &quot;2.2 Согласованность системы культивации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>C05</td><td>Согласованность общего числа систем</td><td>Общее число Исходных Систем Культивации всегда равно трёмстам; не может быть увеличено или уменьшено</td><td>Расплывчатые формулировки: «более трёхсот», «несколько сотен»</td></tr><tr><td>C06</td><td>Согласованность классификации систем</td><td>Всегда разделены на шесть больших категорий (исходная дедукция, жизненный цикл, пространственные правовые принципы, возвышение сознания, симбиотическая сеть, прикладная инженерия), по пятьдесят систем в каждой</td><td>Другие способы классификации или несогласованное число категорий</td></tr><tr><td>C07</td><td>Согласованность Трёх Исходных Основ</td><td>Первые три системы всегда — Дедуктивная Итерация (001), Жизненный Цикл (002) и Регулирование Пространственных Правовых Принципов (003)</td><td>Изменение номеров или названий первых трёх систем</td></tr><tr><td>C08</td><td>Согласованность настройки Плода Умножения</td><td>Плод Умножения всегда является «стартовым баффом», дающим стократное дедуктивное усиление, и получил технологическое применение</td><td>Описание Плода Умножения как природного плода или как не технологизированного</td></tr><tr><td>C09</td><td>Согласованность стадий культивации</td><td>Деления стадий каждой системы согласуются с документом 14 «Единое Разделение Стадий Культивации»</td><td>Изобретение названий стадий, противоречащих единому разделению</td></tr><tr><td>C10</td><td>Согласованность анти-хищнической позиции</td><td>Хищническая культивация не может описываться как положительная или приемлемая система</td><td>Защита или приукрашивание хищнической культивации</td></tr></tbody></table><h3 id="_2-3-социальная-и-правовая-согласованность" tabindex="-1">2.3 Социальная и правовая согласованность <a class="header-anchor" href="#_2-3-социальная-и-правовая-согласованность" aria-label="Permalink to &quot;2.3 Социальная и правовая согласованность&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>C11</td><td>Согласованность типов цивилизаций</td><td>Всегда Пять типов (восточноазиатский интенсивный, скандинавский социальный, североамериканский плюралистический, континентальный европейский социальный, развивающийся догоняющий)</td><td>Появляется шестой тип или изменяются названия типов</td></tr><tr><td>C12</td><td>Согласованность правовой системы</td><td>Всегда Конституция + Трудовой Закон + Закон о защите потребителей + пять сопроводительных законов (образование, здравоохранение, жильё, окружающая среда, антимонопольное регулирование)</td><td>Опущение какого-либо закона или добавление неустановленного закона</td></tr><tr><td>C13</td><td>Согласованность структуры управления</td><td>Всегда Собрание Якоря (законодательная) + Симбиотический Исполнительный Комитет (исполнительная) + Симбиотический Суд (судебная) + Надзорный Комитет Якоря (надзорная)</td><td>Изменение названий институтов или распределения властей</td></tr><tr><td>C14</td><td>Согласованность Механизма подряда, связанного с результатом</td><td>Всегда в центре «больше труда — больше выгоды»; распределение ресурсов основано на вкладе</td><td>Описание подряда, связанного с результатом, как уравниловки или распределения по потребностям</td></tr><tr><td>C15</td><td>Согласованность Стратегии активации 20 %</td><td>Всегда активация 20 % живых существ как Верховных Силачей Плоскости на раннем этапе</td><td>Изменение процента активации или цели</td></tr></tbody></table><h2 id="iii-проверки-межмодульнои-логическои-согласованности" tabindex="-1">III. Проверки межмодульной логической согласованности <a class="header-anchor" href="#iii-проверки-межмодульнои-логическои-согласованности" aria-label="Permalink to &quot;III. Проверки межмодульной логической согласованности&quot;">​</a></h2><h3 id="_3-1-согласованность-линии-времени" tabindex="-1">3.1 Согласованность линии времени <a class="header-anchor" href="#_3-1-согласованность-линии-времени" aria-label="Permalink to &quot;3.1 Согласованность линии времени&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>L01</td><td>Согласованность дат исторических событий</td><td>Даты всех исторических событий согласуются с документом 93 «Сводная таблица деления эпох» и документами 70-79</td><td>Одно и то же событие имеет разные даты в разных документах</td></tr><tr><td>L02</td><td>Согласованность деления эпох</td><td>Названия эпох и даты начала и конца согласуются с документом 70 «Сводная таблица деления эпох»</td><td>Появляются неустановленные эпохи или изменяются границы эпох</td></tr><tr><td>L03</td><td>Согласованность периодов персонажей</td><td>Периоды активности ключевых личностей согласуются с документом 95 «Ключевые Личности и Организации»</td><td>Персонаж появляется в эпохе, в которой не существовал</td></tr><tr><td>L04</td><td>Согласованность дат технологий</td><td>Даты изобретения и созревания каждой технологии согласуются с хроникой</td><td>Технология используется в эпоху, предшествующую её изобретению</td></tr></tbody></table><h3 id="_3-2-согласованность-технологическои-системы" tabindex="-1">3.2 Согласованность технологической системы <a class="header-anchor" href="#_3-2-согласованность-технологическои-системы" aria-label="Permalink to &quot;3.2 Согласованность технологической системы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>T01</td><td>Согласованность технологии Зеркала Репликации</td><td>Зеркало Репликации всегда «устройство копирования 1:1, не соприкасающееся с оригиналом», с нулевым вмешательством в процесс копирования</td><td>Описание Зеркала Репликации как способного изменять оригинал или требующего контакта с оригиналом</td></tr><tr><td>T02</td><td>Согласованность изолированного пространства</td><td>Изолированное пространство всегда «независимое пространство, полностью отделённое от внешнего мира барьерами законов»</td><td>Описание изолированного пространства как обычной комнаты или виртуального пространства</td></tr><tr><td>T03</td><td>Согласованность требований культивации пространственных правовых принципов</td><td>Требования культивации каждой пространственной технологии согласуются с документом 13 «Подробное описание Системы Регулирования Пространственных Правовых Принципов»</td><td>Культиваторы низких стадий используют технологии, требующие высоких стадий</td></tr><tr><td>T04</td><td>Согласованность единиц энергии</td><td>Измерение энергии единообразно использует «стандартную единицу энергии»; другие единицы не допускаются</td><td>Смешение нестандартных единиц: «духовные камни», «кристаллические монеты» и т. п.</td></tr></tbody></table><h3 id="_3-3-согласованность-межплоскостных-и-временных-правил" tabindex="-1">3.3 Согласованность межплоскостных и временных правил <a class="header-anchor" href="#_3-3-согласованность-межплоскостных-и-временных-правил" aria-label="Permalink to &quot;3.3 Согласованность межплоскостных и временных правил&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>K01</td><td>Согласованность «сначала наблюдение, потом ограниченное вмешательство»</td><td>Все операции возврата времени и межплоскостные операции должны следовать этому принципу; этап наблюдения не может пропускаться</td><td>Описание операций с прямым вмешательством без наблюдения</td></tr><tr><td>K02</td><td>Согласованность «передачи только знаний»</td><td>Археологический результат ограничен абстрактными знаниями и информацией; материя, энергия или формы жизни не могут быть переданы</td><td>Описание приноса артефактов или образцов в родную плоскость</td></tr><tr><td>K03</td><td>Согласованность системы разрешений на перемещение</td><td>Все перемещения между плоскостями должны получать разрешение соответствующего уровня; перемещение без разрешения не допускается</td><td>Описание несанкционированных перемещений</td></tr><tr><td>K04</td><td>Согласованность классификации временных парадоксов</td><td>Парадоксы всегда делятся на четыре категории — отцеубийства, информационный, онтологический и событийный; добавления или изменения не допускаются</td><td>Появляются неустановленные типы парадоксов</td></tr><tr><td>K05</td><td>Согласованность классификации плоскостей</td><td>Плоскости всегда делятся на пять больших категорий (материально-субстанциональные, энерго-проявленные, сознание-доминирующие, законо-фрагментированные, близкие к истоку)</td><td>Появляются другие способы классификации</td></tr></tbody></table><h3 id="_3-4-согласованность-жизни-и-рас" tabindex="-1">3.4 Согласованность жизни и рас <a class="header-anchor" href="#_3-4-согласованность-жизни-и-рас" aria-label="Permalink to &quot;3.4 Согласованность жизни и рас&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>S01</td><td>Согласованность классификации рас</td><td>Расы всегда делятся на восемь больших категорий (гуманоидная, звериная, растительная, элементарная, энергетическая, сознательная, механическая, смешанная формы)</td><td>Появляются другие способы классификации</td></tr><tr><td>S02</td><td>Согласованность обращения с аномальной жизнью</td><td>Аномальная жизнь всегда обрабатывается по трём типам стандартизированных процедур</td><td>Описание произвольного обращения вне процедур</td></tr><tr><td>S03</td><td>Согласованность обращения с тёмными замещающими сущностями</td><td>Тёмные замещающие сущности всегда обрабатываются по Этике Двойной Души и правилам обращения четырёх ветвей</td><td>Описание простого устранения одной души</td></tr><tr><td>S04</td><td>Согласованность равенства Десяти Тысяч Рас</td><td>Все разумные расы равны перед законом; настройки расовой дискриминации не допускаются</td><td>Описание какой-либо расы как естественно низшей или обречённой на рабство</td></tr></tbody></table><h2 id="iv-проверки-формата-и-норм-документов" tabindex="-1">IV. Проверки формата и норм документов <a class="header-anchor" href="#iv-проверки-формата-и-норм-документов" aria-label="Permalink to &quot;IV. Проверки формата и норм документов&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Пункт контроля</th><th>Содержание контроля</th><th>Критерий прохождения</th><th>Частые проблемы</th></tr></thead><tbody><tr><td>F01</td><td>Правильность формата имени файла</td><td>Формат имени файла — «XX-Название документа.md», где XX — двузначный номер</td><td>Отсутствие номера, пробелы в названии, неверное расширение файла</td></tr><tr><td>F02</td><td>Полнота информационного блока документа</td><td>В начале есть информационная таблица с номером, модулем и ключевыми словами (3-5)</td><td>Блок отсутствует или поля неполны</td></tr><tr><td>F03</td><td>Достаточность заголовков второго уровня</td><td>Основной текст содержит не менее 3 разделов с заголовками второго уровня</td><td>Менее 3 заголовков второго уровня</td></tr><tr><td>F04</td><td>Использование структурированных элементов</td><td>Для улучшения читаемости используются списки, таблицы и другие структурированные элементы</td><td>Сплошные текстовые абзацы без списков и таблиц</td></tr><tr><td>F05</td><td>Наличие заключения</td><td>В конце есть абзац «Заключение»</td><td>Отсутствие заключения</td></tr><tr><td>F06</td><td>Наличие связанных документов</td><td>В конце перечислены 2-3 номера и названия связанных документов</td><td>Связанные документы отсутствуют или не существуют</td></tr><tr><td>F07</td><td>Достаточность объёма</td><td>Основной текст не менее 800 знаков (без учёта заголовков и метаинформации)</td><td>Основной текст менее 800 знаков</td></tr><tr><td>F08</td><td>Единство терминологии</td><td>Используются стандартные термины: «Вселенная Хэнъюань», «Якорь», «Симбиоз» и др.</td><td>Неединая терминология или нестандартные формулировки</td></tr><tr><td>F09</td><td>Уместность стиля написания</td><td>Серьёзный, систематизированный стиль документа сеттинга без разговорных выражений</td><td>Появление разговорных или небрежных выражений</td></tr><tr><td>F10</td><td>Соответствие номеров списку</td><td>Номера и названия документов соответствуют полному списку 100 документов в SPEC.md</td><td>Номера или названия не соответствуют списку</td></tr></tbody></table><h2 id="v-процесс-самопроверки-и-порядок-использования" tabindex="-1">V. Процесс самопроверки и порядок использования <a class="header-anchor" href="#v-процесс-самопроверки-и-порядок-использования" aria-label="Permalink to &quot;V. Процесс самопроверки и порядок использования&quot;">​</a></h2><h3 id="_5-1-процесс-самопроверки-при-создании-новых-настроек" tabindex="-1">5.1 Процесс самопроверки при создании новых настроек <a class="header-anchor" href="#_5-1-процесс-самопроверки-при-создании-новых-настроек" aria-label="Permalink to &quot;5.1 Процесс самопроверки при создании новых настроек&quot;">​</a></h3><ol><li><strong>Предварительная самопроверка</strong> : после завершения создания создатель проверяет пункт за пунктом по настоящему списку и отмечает проблемные пункты.</li><li><strong>Доработка и совершенствование</strong> : внести исправления в отмеченные проблемные пункты, обеспечив прохождение всех.</li><li><strong>Перекрёстная проверка</strong> : передать другому создателю сеттинга для перекрёстной проверки, с особым вниманием к межмодульной согласованности.</li><li><strong>Утверждение Комитета</strong> : крупные изменения сеттинга должны быть представлены на утверждение Комитета по Обслуживанию Сеттинга.</li><li><strong>Архивное обновление</strong> : после прохождения всех проверок официально включить в систему сеттинга и обновить связанные индексные документы.</li></ol><h3 id="_5-2-процесс-самопроверки-при-пересмотре-старых-настроек" tabindex="-1">5.2 Процесс самопроверки при пересмотре старых настроек <a class="header-anchor" href="#_5-2-процесс-самопроверки-при-пересмотре-старых-настроек" aria-label="Permalink to &quot;5.2 Процесс самопроверки при пересмотре старых настроек&quot;">​</a></h3><ol><li><strong>Оценка воздействия</strong> : оценить другие документы и модули сеттинга, на которые пересмотренное содержание может повлиять.</li><li><strong>Проверки связанных документов</strong> : провести проверки согласованности всех затронутых связанных документов.</li><li><strong>Синхронный пересмотр</strong> : синхронно пересмотреть затронутое содержание в связанных документах.</li><li><strong>Запись версии</strong> : зафиксировать содержание пересмотра и номер версии в документе 99 «Версия Документов и Пояснения по Обслуживанию».</li><li><strong>Уведомление-объявление</strong> : по крупным пересмотрам необходимо публиковать объявление об изменениях всем пользователям сеттинга.</li></ol><h3 id="_5-3-периодическая-всесторонняя-самопроверка" tabindex="-1">5.3 Периодическая всесторонняя самопроверка <a class="header-anchor" href="#_5-3-периодическая-всесторонняя-самопроверка" aria-label="Permalink to &quot;5.3 Периодическая всесторонняя самопроверка&quot;">​</a></h3><p>Комитет по Обслуживанию Сеттинга ежеквартально проводит всестороннюю самопроверку согласованности сеттинга, систематически проверяя все 100 документов на предмет потенциальных противоречий сеттинга и логических несоответствий. Результаты самопроверки оформляются в «Квартальный Отчёт о Согласованности Сеттинга» и публикуются для всех пользователей сеттинга.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Список Самопроверки Противоречий Сеттинга — это «конституция качества» системы сеттинга Симбиотической Цивилизации Якоря. Благодаря систематизированным, списковым пунктам контроля он гарантирует, что система сеттинга в процессе непрерывного расширения и пересмотра всегда сохраняет логическую самосогласованность и терминологическое единство. Обширная система сеттинга боится не столько недостаточной богатства содержания, сколько внутренних противоречий и несогласованности между частями. Существование настоящего списка самопроверки предназначено именно для того, чтобы система сеттинга Симбиотической Цивилизации Якоря, сохраняя открытость и рост, всегда обладала прочным фундаментом согласованности.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>99-文档版本与维护说明 (Версия Документов и Пояснения по Обслуживанию)</li><li>90-术语词典 (Словарь Терминов)</li><li>00-衡元宙宇宙总览 (Хэн Юаньчжоу: Обзор Вселенной)</li></ul>',33)])])}const u=d(h,[["render",i]]);export{c as __pageData,u as default};
